// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata, uint256[] calldata) public {
        address[] memory tos;
        uint256[] memory vals;
        vm.assume(tos.length == 0 && vals.length == 0);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, tos, vals));
        assertTrue(!success, "transfer should revert when called with empty arrays");
    }
}

